    var body:some View {Page{Text("أدوات بيتك").font(.title.bold());NavigationLink{AccountsView(open:open)}label:{link("الحسابات وهدف الادخار","wallet.pass")};NavigationLink{BudgetView(period:period)}label:{link("ميزانية الدورة","chart.pie")};NavigationLink{DuesView(open:open)}label:{link("الفواتير والأقساط","calendar.badge.clock")};NavigationLink{TemplatesView(open:open)}label:{link("القوالب السريعة","square.grid.2x2")};NavigationLink{CategoriesView(open:open)}label:{link("التصنيفات","tag")};NavigationLink{SettingsView(period:period,open:open)}label:{link("الإعدادات والخصوصية","gearshape")}.accessibilityIdentifier("more-settings");NavigationLink{BackupView(period:period)}label:{link("النسخ الاحتياطي والتقارير","square.and.arrow.up")}.accessibilityIdentifier("more-backup")}.buttonStyle(.plain)}
