struct BudgetView:View {
    @EnvironmentObject var store:Store;var period:Cycle
    @State var category="";@State var amount="";@State var error:String?
    var body:some View {if let h=store.data{let spent=Finance.expense(h.transactions,period);Page{Text("ميزانية الدورة").font(.title.bold());if let b=h.budget(period){MewCard(prominent:true){VStack(alignment:.leading,spacing:10){MoneyView(label:"المتبقي من ميزانية البيت",amount:b.amount-spent,main:true);ProgressView(value:b.amount>0 ? min(1,max(0,Double(spent)/Double(b.amount))):0);Hint("المحدد "+Finance.format(b.amount)+" • المصروف "+Finance.format(spent))}}};MewCard{VStack(alignment:.leading,spacing:12){Picker("الميزانية",selection:$category){Text("البيت بالكامل").tag("");ForEach(h.categories.filter{!$0.income && !$0.archived}){Text($0.name).tag($0.id)}};FormField(label:"المبلغ المحدد — جنيه",text:$amount,number:true,identifier:"budget-amount");Hint("ميزانيات البنود جزء من ميزانية البيت؛ لا تُجمع معه لحساب الإنفاق");if let error{Text(error).foregroundStyle(.red)};Button("حفظ الميزانية"){do{let b=Budget(period:period.start,amount:try Finance.money(amount),categoryId:category.isEmpty ? nil:category);Task{_ = await store.change{h in h.budgets.removeAll{$0.id==b.id};h.budgets.append(b)}}}catch{self.error=error.localizedDescription}}.buttonStyle(.borderedProminent).accessibilityIdentifier("budget-save")}}
        let budgets=h.budgets.filter{$0.period==period.start};let distribution=Finance.categories(h.transactions,period);let allocated=budgets.filter{$0.categoryId != nil}.reduce(0){$0+$1.amount};if let total=h.budget(period){Hint(allocated>total.amount ? "مجموع ميزانيات البنود يتجاوز ميزانية البيت":"ميزانية غير موزعة "+Finance.format(total.amount-allocated))};ForEach(budgets){b in MewCard{VStack(alignment:.leading,spacing:10){let value=b.categoryId==nil ? spent:distribution[b.categoryId!,default:0];MoneyView(label:b.categoryId==nil ? "البيت بالكامل":h.category(b.categoryId),amount:b.amount-value);Hint("المحدد "+Finance.format(b.amount)+" • المصروف "+Finance.format(value));if value>b.amount{Text("تجاوز "+Finance.format(value-b.amount)).foregroundStyle(.red)};Button("إزالة الميزانية",role:.destructive){Task{_ = await store.change{h in h.budgets.removeAll{$0.id==b.id}}}}}};if !budgets.isEmpty{Button("نسخ الميزانيات الناقصة للدورة التالية"){Task{_ = await store.change{h in let next=h.cycle(period.end);for b in budgets where h.budget(next,category:b.categoryId)==nil{h.budgets.append(Budget(period:next.start,amount:b.amount,categoryId:b.categoryId))}}}}}else{EmptyState(title:"لا توجد ميزانية",detail:"حدد مبلغًا للبيت أو لأحد البنود")}
    }.onAppear{fill(h)}.onChange(of:category){_,_ in fill(store.data ?? h)}}}
    func fill(_ h:Household){amount=h.budget(period,category:category.isEmpty ? nil:category).map{Finance.input($0.amount)} ?? ""}
}
struct AccountsView:View {
    @EnvironmentObject var store:Store;var open:(EditorRoute)->Void
    var body:some View{if let h=store.data{Page{Text("حساباتي ومحافظي").font(.title.bold());MoneyView(label:"إجمالي الأرصدة الحالية",amount:h.accounts.reduce(0){$0+h.balance($1)},main:true);Button("إضافة حساب أو محفظة"){open(EditorRoute(kind:"account"))}.buttonStyle(.borderedProminent);ForEach(h.accounts){a in MewCard{VStack(alignment:.leading,spacing:12){Text(a.name).font(.headline);Hint(a.kind+(a.archived ? " • مؤرشف":""));MoneyView(label:"الرصيد الحالي",amount:h.balance(a));Hint("افتتاحي "+Finance.format(a.opening));ViewThatFits{HStack{controls(a,h)};VStack(alignment:.leading){controls(a,h)}}}}};MewCard{VStack(alignment:.leading,spacing:12){Text("هدف الادخار").font(.headline);if h.prefs.goal.target>0{MoneyView(label:h.prefs.goal.title,amount:h.prefs.goal.target);let account=h.accounts.first{$0.id==h.prefs.goal.accountId};let balance=account.map{h.balance($0)} ?? h.accounts.reduce(0){$0+h.balance($1)};MoneyView(label:"الرصيد المخصص",amount:balance);ProgressView(value:min(1,max(0,Double(balance)/Double(h.prefs.goal.target))))};Button("تحديد أو تعديل الهدف"){open(EditorRoute(kind:"goal"))};Hint("اختر حساب ادخار مخصصًا؛ التحويل إليه ليس مصروفًا")}};Hint("قد يظهر رصيد سالب إذا سجلت صرفًا أكبر من الرصيد؛ راجع السجلات دون إنشاء دخل وهمي")}}}
    @ViewBuilder func controls(_ a:Account,_ h:Household)->some View{Button("تعديل"){open(EditorRoute(kind:"account",account:a))};if !a.archived{Button(h.prefs.defaultAccount==a.id ? "افتراضي ✓":"اجعله افتراضيًا"){Task{_ = await store.change{$0.prefs.defaultAccount=a.id}}}};Button(a.archived ? "إلغاء الأرشفة":"أرشفة"){Task{_ = await store.change{h in let others=h.accounts.filter{!$0.archived && $0.id != a.id};try require(a.archived || !others.isEmpty,"احتفظ بحساب نشط واحد على الأقل");h.accounts=h.accounts.map{var v=$0;if v.id==a.id{v.archived.toggle()};return v};if !a.archived && h.prefs.defaultAccount==a.id{h.prefs.defaultAccount=others.first?.id}}}}}
}
struct DuesView:View {
    @EnvironmentObject var store:Store;var open:(EditorRoute)->Void
    @State var showPaid=false;@State var editing:Due?;@State var amount="";@State var error:String?
    var body:some View{if let h=store.data{Page{Text("الفواتير والأقساط").font(.title.bold());Button("التزام متكرر جديد"){open(EditorRoute(kind:"rule"))}.buttonStyle(.borderedProminent);Hint("المتأخرات والاستحقاقات خلال 60 يومًا. لا تدخل المبالغ المخططة المصروف قبل السداد.");Toggle("إظهار المدفوع أيضًا",isOn:$showPaid);let dues=h.dues.filter{(showPaid || h.remaining($0)>0) && $0.date<=Dates.add(Dates.today(),days:60)};if dues.isEmpty{EmptyState(title:"لا توجد استحقاقات مطابقة",detail:"أضف فاتورة أو قسطًا للتذكير وتنظيم السداد")};ForEach(dues){d in MewCard{VStack(alignment:.leading,spacing:12){Text(d.title).font(.headline);Hint(d.date+" • "+h.category(d.categoryId)+" • "+(h.remaining(d)==0 ? "مدفوع":d.date<Dates.today() ? "متأخر":h.paid(d)>0 ? "مدفوع جزئيًا":"مستحق"));MoneyView(label:"المتبقي",amount:h.remaining(d));Hint("مخطط "+Finance.format(d.amount)+" • مدفوع "+Finance.format(h.paid(d)));if h.remaining(d)>0{Button("تسجيل سداد"){open(EditorRoute(kind:"due",due:d))}};Button("تعديل مبلغ هذا الاستحقاق"){amount=Finance.input(d.amount);editing=d}}}};Text("إدارة التكرار").font(.headline);ForEach(h.rules){r in MewCard{VStack(alignment:.leading,spacing:10){Text(r.title).font(.headline);Hint(r.active ? "نشط":"متوقف");Button("تعديل"){open(EditorRoute(kind:"rule",rule:r))};Button(r.active ? "إيقاف":"تفعيل"){Task{_ = await store.change{h in h.rules=h.rules.map{var v=$0;if v.id==r.id{v.active.toggle()};return v};if r.active{h.dues.removeAll{d in d.ruleId==r.id && d.date>Dates.today() && !h.transactions.contains{$0.dueId==d.id}}}}}}}};Hint("إيقاف التكرار يزيل المواعيد المستقبلية غير المرتبطة بالسداد؛ السجل السابق يبقى")}.sheet(item:$editing){d in EditorFrame(title:"المبلغ المخطط",save:{do{let value=try Finance.money(amount);try require(value>0 && value>=(store.data ?? h).paid(d),"المبلغ أكبر من صفر ولا يقل عن المدفوع");Task{if await store.change(transform:{h in h.dues=h.dues.map{var v=$0;if v.id==d.id{v.amount=value};return v}}){editing=nil}}}catch{self.error=error.localizedDescription}}){Hint(d.title+" • "+d.date);FormField(label:"المبلغ — جنيه",text:$amount,number:true);Hint("لهذا الموعد فقط؛ لا يغيّر القاعدة المستقبلية أو المصروف الفعلي");if let error{Text(error).foregroundStyle(.red)}}}}}
}
