    var body:some View{if let h=store.data{Page{Text("القوالب السريعة").font(.title.bold());Button("قالب جديد"){open(EditorRoute(kind:"template"))}.buttonStyle(.borderedProminent);if h.templates.isEmpty{EmptyState(title:"وفّر خطوات الإدخال",detail:"احفظ مصروفًا أو دخلًا متكررًا كقالب؛ كل استخدام يفتح مسودة للمراجعة")};ForEach(h.templates){t in MewCard{VStack(alignment:.leading,spacing:12){Text(t.title).font(.headline);MoneyView(label:t.type.title,amount:t.amount);Hint(h.account(t.accountId)+" • "+h.category(t.categoryId));Button("استخدام القالب"){open(EditorRoute(kind:t.type == .income ? "income":"expense",template:t))}.disabled(!h.templateAvailable(t));Button("تعديل"){open(EditorRoute(kind:"template",template:t))};Button("حذف",role:.destructive){Task{_ = await store.change{h in h.templates.removeAll{$0.id==t.id}}}}}}}}}
