}
struct ByteDocument:FileDocument {
    static var readableContentTypes:[UTType]{[.data,.pdf,.commaSeparatedText]};var bytes:Data
    init(_ data:Data){bytes=data};init(configuration:ReadConfiguration)throws{bytes=configuration.file.regularFileContents ?? Data()};func fileWrapper(configuration:WriteConfiguration)throws->FileWrapper{FileWrapper(regularFileWithContents:bytes)}
}
struct BackupView:View {
    @EnvironmentObject var store:Store;var period:Cycle
    @State var password="";@State var importing=false;@State var exporting=false;@State var document=ByteDocument(Data());@State var contentType=UTType.data;@State var filename="Mew.hbb";@State var reportKind="";@State var warning=false;@State var undo=false
    var body:some View{Page{Text("نسخة احتياطية وتقارير").font(.title.bold());MewCard{VStack(alignment:.leading,spacing:12){Text("نسخة مشفرة بكلمة مرور").font(.headline);SecureField("كلمة المرور — 8 أحرف على الأقل",text:$password).textFieldStyle(.roundedBorder).accessibilityIdentifier("backup-password");Hint("ملف HBB متوافق مع Android. احتفظ بكلمة المرور؛ لا توجد خدمة لاستعادتها.");Button("حفظ نسخة مشفرة"){Task{guard let h=store.data,let repo=store.repository else{return};do{document=ByteDocument(try await repo.exportBackup(h,password:password));password="";contentType = .data;filename="Mew-"+Dates.today()+".hbb";exporting=true}catch{store.message=error.localizedDescription}}}.disabled(store.data==nil || store.busy);Button("اختيار نسخة للاستعادة"){importing=true}.disabled(store.busy);Button("الرجوع لنسخة الأمان السابقة"){undo=true}.disabled(store.data==nil);Hint("الاستعادة تستبدل البيانات دون دمج بعد عرض ملخص وتأكيد. احفظ نسخة قبل نقل الهاتف أو حذف التطبيق.")}}
        if store.data != nil{MewCard{VStack(alignment:.leading,spacing:12){Text("تقرير الدورة المختارة").font(.headline);Hint(period.start+" إلى "+Dates.add(period.end,days:-1));Button("تصدير CSV"){reportKind="csv";warning=true};Button("تصدير PDF"){reportKind="pdf";warning=true};Hint("التقارير غير مشفرة وليست بديلًا عن النسخة الاحتياطية")}}}
    }.fileExporter(isPresented:$exporting,document:document,contentType:contentType,defaultFilename:filename){result in switch result{case .success:store.message="تم تصدير الملف";case .failure:store.message="تعذر التصدير؛ اختر مكانًا صالحًا"};document=ByteDocument(Data())}
    .fileImporter(isPresented:$importing,allowedContentTypes:[.data],allowsMultipleSelection:false){result in switch result{case .success(let urls):guard let url=urls.first else{return};let secret=password;password="";Task{let opened=url.startAccessingSecurityScopedResource();defer{if opened{url.stopAccessingSecurityScopedResource()}};do{let size=try url.resourceValues(forKeys:[.fileSizeKey]).fileSize ?? 0;try require(size<=BackupCrypto.maxSize,"النسخة أكبر من 32 ميجابايت");let bytes=try Data(contentsOf:url);await store.inspect(bytes,password:secret)}catch{store.message=error.localizedDescription}};case .failure:store.message="لم يتم اختيار نسخة؛ لم تتغير البيانات"}}
    .alert("تصدير بيانات مالية غير مشفرة",isPresented:$warning){Button("اختيار مكان الحفظ"){guard let h=store.data else{return};document=ByteDocument(reportKind=="csv" ? Reports.csv(h,period):PDFReport.make(h,period));contentType=reportKind=="csv" ? .commaSeparatedText:.pdf;filename="Mew-"+period.start+(reportKind=="csv" ? ".csv":".pdf");exporting=true};Button("إلغاء",role:.cancel){}}message:{Text("اختر مكانًا تثق به؛ الملف يحتوي تفاصيل الحسابات")}
    .alert("استبدال البيانات الحالية؟",isPresented:Binding(get:{store.restorePreview != nil},set:{if !$0{store.restorePreview=nil}})){Button("استعادة",role:.destructive){Task{await store.restore()}};Button("إلغاء",role:.cancel){store.restorePreview=nil}}message:{if let h=store.restorePreview{Text("\(h.accounts.count) حساب • \(h.transactions.count) عملية • \(h.plans.count) خطة. ستبقى إعدادات قفل هذا الهاتف، وستُحفظ نسخة أمان قبل الاستبدال.")}}
    .alert("الرجوع للبيانات السابقة؟",isPresented:$undo){Button("الرجوع",role:.destructive){Task{await store.undoRestore()}};Button("إلغاء",role:.cancel){}}message:{Text("ستُستبدل البيانات الحالية بنسخة الأمان قبل آخر استعادة؛ احفظ نسخة من العمليات الجديدة أولًا")}
    }
