struct SearchView:View {
    @EnvironmentObject var store:Store;var open:(EditorRoute)->Void;var navigate:(String)->Void
    @State var query=""
    var body:some View{Page{Text("ابحث في بيتك").font(.title.bold());TextField("تصنيف، مبلغ، حساب، موعد أو إجراء",text:$query).textFieldStyle(.roundedBorder).accessibilityIdentifier("global-search");if let h=store.data{let hits=Search.hits(h,query:query);if hits.isEmpty{Hint(query.isEmpty ? "جرّب: الطعام، 100.00، أو نسخة احتياطية":"لا توجد نتائج مطابقة")};ForEach(hits){hit in Button{switch hit.kind{case "transaction":open(EditorRoute(kind:"transaction",transaction:h.transactions.first{$0.id==hit.id}));case "due":open(EditorRoute(kind:"due",due:h.dues.first{$0.id==hit.id}));case "account":open(EditorRoute(kind:"account",account:h.accounts.first{$0.id==hit.id}));case "category":open(EditorRoute(kind:"category",category:h.categories.first{$0.id==hit.id}));default:navigate(hit.id)}}label:{MewCard{VStack(alignment:.leading,spacing:8){Text(hit.title).font(.headline);Hint(hit.detail)}}}.buttonStyle(.plain)}}}.navigationTitle("البحث")}
}
